<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:18mm}body{font-family:DejaVu Sans,sans-serif;color:#173b72;font-size:12px}h1,h2,h3{text-align:center;margin:4px}h1{font-size:22px;text-decoration:underline}h3{color:#64748b;letter-spacing:1px;margin:22px 0}.firm{text-align:center;border-bottom:2px solid #2563eb;padding-bottom:12px}.recipient{border-left:4px solid #2563eb;padding:10px;margin:18px 0}table{border-collapse:collapse;width:100%;margin-top:18px}th,td{border:1px solid #9eb6d1;padding:9px}th{background:#344bd2;color:#fff;text-align:left}.right{text-align:right}.total{background:#172554;color:#fff;font-weight:bold}.sign{margin-top:70px;display:flex;justify-content:space-between}</style></head><body><div class="firm"><h1>{{ strtoupper($firm->name) }}</h1><div>{{ $firm->address }}<br>VAT No: {{ $firm->pan_no }} · {{ $firm->phone }}</div></div><h3>PURCHASE BALANCE CONFIRMATION</h3><div class="recipient"><strong>Company: {{ $company }}</strong><br>Period: {{ $periodFrom }} to {{ $periodTo }}<br>B.S.: {{ $periodFromBs }} to {{ $periodToBs }}<br>Printed B.S. Date: {{ $bsDate }}</div><p>We confirm that the following purchase transactions are recorded with our organization for the stated period.</p><table><thead><tr><th>Description</th><th class="right">Amount (NPR)</th></tr></thead><tbody><tr><td>Taxable Purchases</td><td class="right">{{ number_format($taxablePurchases,2) }}</td></tr><tr><td>Non-taxable Purchases</td><td class="right">{{ number_format($nonTaxablePurchases,2) }}</td></tr><tr><td>VAT (13%)</td><td class="right">{{ number_format($vatAmount,2) }}</td></tr><tr class="total"><td>Total Purchase Amount</td><td class="right">{{ number_format($total,2) }}</td></tr></tbody></table><p>Opening Balance: Rs {{ number_format($openingBalance,2) }} &nbsp;&nbsp;&nbsp; Closing Balance: Rs {{ number_format($closingBalance,2) }}</p><p style="margin-top:40px">Kindly verify the above figures and return a duly signed and stamped copy.</p><div class="sign"><span>Prepared By: ____________</span><span>Authorized Signature: ____________</span></div></body></html>
